package ama.transcript;
import java.util.*;import java.nio.charset.StandardCharsets;import ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Presentation of an already verified frozen snapshot; no latest/current/default lookup. */
final class FrozenFinalProjection {
 static Map<String,Object> project(JdbcMinutesFactsReader.Snapshot snapshot,String id){var rows=snapshot.facts().rows();reserve(snapshot);var frozen=one(rows,Table.FINAL_CONFIRMATION,id);var body=one(rows,Table.MINUTES_REVISION,frozen.string("minutes_revision_id"));var set=one(rows,Table.ELEMENT_SET,frozen.string("element_set_id"));var reviewIds=rows.stream().filter(r->r.table()==Table.FINAL_RESULT_REVIEW&&id.equals(r.string("confirmation_id"))).map(r->r.string("review_id")).sorted().toList();var reviews=new ArrayList<Map<String,Object>>();for(String review:reviewIds)reviews.add(JdbcMinutesSavedQueries.project(one(rows,Table.RESULT_REVIEW,review)));var profiles=new ArrayList<Map<String,Object>>();for(var config:snapshot.facts().configurations().stream().sorted(Comparator.comparing(GenerationConfiguration::inputId)).toList()){var definitions=new TreeMap<String,Object>();for(var kind:ProfileKind.values())definitions.put(kind.name(),artifact(config.profiles().definition(kind)));profiles.add(JdbcMinutesSavedQueries.map("generationInputId",config.inputId(),"prompt",artifact(config.prompt()),"model",artifact(config.model()),"definitions",Collections.unmodifiableMap(definitions)));}
  var result=JdbcMinutesSavedQueries.map("confirmation",JdbcMinutesSavedQueries.project(frozen),"body",JdbcMinutesSavedQueries.project(body),"set",JdbcMinutesSavedQueries.project(set),"elements",elements(rows,set.string("id")),"reviewIds",reviewIds,"reviews",List.copyOf(reviews),"profiles",List.copyOf(profiles),"provenanceVerified",true,"observation",JdbcMinutesSettingsReceipts.observation(snapshot.observation()));return result;
 }
 static Map<String,Object> elements(List<FullRow> rows,String set){var result=new LinkedHashMap<String,Object>();for(var category:Category.values()){var items=new ArrayList<Object>();for(var row:rows.stream().filter(r->r.table()==Table.MINUTES_ELEMENT&&set.equals(r.string("set_id"))&&category.name().equals(r.string("category"))).sorted(Comparator.comparingLong((FullRow r)->r.number("ordinal")).thenComparing(r->r.string("id"))).toList()){var actions=rows.stream().filter(r->r.table()==Table.ACTION_ITEM&&row.string("id").equals(r.string("element_id"))).toList();require(actions.size()<=1,PROVENANCE_UNAVAILABLE);items.add(JdbcMinutesSavedQueries.map("id",row.string("id"),"body",row.string("body"),"ordinalToken",Long.toString(row.number("ordinal")),"supportState",row.string("support_state"),"action",actions.isEmpty()?null:JdbcMinutesSavedQueries.project(actions.getFirst())));}result.put(category.name(),List.copyOf(items));}return Collections.unmodifiableMap(result);}
 private static Map<String,Object> artifact(Artifact value){return Map.of("version",value.version(),"sha256",value.sha256());}
 private static FullRow one(List<FullRow> rows,Table table,String id){var selected=rows.stream().filter(r->r.table()==table&&id.equals(r.string("id"))).toList();require(selected.size()==1,PROVENANCE_UNAVAILABLE);return selected.getFirst();}
 private static void reserve(JdbcMinutesFactsReader.Snapshot snapshot){var budget=snapshot.budget();for(var row:snapshot.facts().rows())if(Set.of(Table.FINAL_CONFIRMATION,Table.MINUTES_REVISION,Table.ELEMENT_SET,Table.MINUTES_ELEMENT,Table.ACTION_ITEM,Table.RESULT_REVIEW,Table.FINAL_RESULT_REVIEW).contains(row.table())){budget.row(row.table().columns().size()*2L);for(var column:row.table().columns())if(row.value(column.name()) instanceof TextCell text){String value=text.value();budget.capture(value.getBytes(StandardCharsets.UTF_8).length,value.codePointCount(0,value.length()),value.length(),8);}}for(var config:snapshot.facts().configurations()){budget.row(8+ProfileKind.values().length*3L);reserve(config.inputId(),budget);reserve(config.prompt().version(),budget);reserve(config.prompt().sha256(),budget);reserve(config.model().version(),budget);reserve(config.model().sha256(),budget);for(var kind:ProfileKind.values()){reserve(kind.name(),budget);reserve(config.profiles().definition(kind).version(),budget);reserve(config.profiles().definition(kind).sha256(),budget);}}}
 private static void reserve(String value,TranscriptAcquisitionBudget.Ledger budget){budget.capture(value.getBytes(StandardCharsets.UTF_8).length,value.codePointCount(0,value.length()),value.length(),4);}
}
